BEGIN;

-- P1-06 canonical scope spelling. Forward correction: do not edit released migration 0002.
ALTER TABLE iam.membership_roles DROP CONSTRAINT IF EXISTS membership_roles_scope_mode_check;
UPDATE iam.membership_roles SET scope_mode='ORG_WIDE' WHERE scope_mode='ORGANISATION';
ALTER TABLE iam.membership_roles ADD CONSTRAINT membership_roles_scope_mode_check CHECK (scope_mode IN ('ORG_WIDE','PROJECT_RESTRICTED'));
ALTER TABLE iam.membership_roles ALTER COLUMN scope_mode SET DEFAULT 'ORG_WIDE';

-- P1-06 canonical permission registry.
ON CONFLICT (permission_key) DO UPDATE SET description=EXCLUDED.description;

-- Remove superseded spelling only after canonical keys exist. ON DELETE CASCADE safely removes old role links.
DELETE FROM iam.permissions WHERE permission_key IN ('organisation.read','organisation.manage');

-- Rebuild system-role permission bundles to exactly match machine registry v1.0.0.
DELETE FROM iam.role_permissions rp USING iam.roles r WHERE rp.role_id=r.id AND r.is_system;
ON CONFLICT DO NOTHING;

COMMIT;
